async function createKnowledgeGraph(config) {
  const p = getPlatform();
  const dataDir2 = config.dataDir;
  if (!p.fs.existsSync(dataDir2)) {
    p.fs.mkdirSync(dataDir2, { recursive: true });
  }
  const db = p.sqlite.openDatabase(p.path.join(dataDir2, "documents.db"));
  const documentStore = new DocumentStore(db);
  const vectorDir = p.path.join(dataDir2, "vectors");
  if (!p.fs.existsSync(vectorDir)) {
    p.fs.mkdirSync(vectorDir, { recursive: true });
  }
  const vectorStore = new VectorStore(vectorDir);
  await vectorStore.initialize();
  const embeddingModel = config.embeddingModel ?? "nomic-embed-text";
  const dimensions = config.embeddingDimensions ?? 768;
  const embeddingPipeline = new EmbeddingPipeline({
    llm: config.llmProvider,
    model: embeddingModel,
    dimensions
  });
  const indexer = new Indexer({
    llm: config.llmProvider,
    documentStore,
    vectorStore,
    embeddingModel,
    embeddingPipeline
  });
  const semanticSearch = new SemanticSearch({
    llm: config.llmProvider,
    documentStore,
    vectorStore,
    embeddingModel,
    embeddingPipeline
  });
  return new KnowledgeGraphImpl(documentStore, vectorStore, indexer, semanticSearch);
}

