var CoreIPCClient = class {
  transport = null;
  signingKey = null;
  // Legacy socket config (if provided)
  socketPath = null;
  signingKeyPath = null;
  // Transport config (if provided)
  providedTransport = null;
  constructor(config) {
    if ("transport" in config) {
      this.providedTransport = config.transport;
      this.signingKey = config.signingKey;
    } else {
      this.socketPath = config.socketPath;
      this.signingKeyPath = config.signingKeyPath;
    }
  }
  async connect() {
    if (this.providedTransport) {
      this.transport = this.providedTransport;
      await this.transport.start();
      return;
    }
    try {
      const keyHex = (await Promise.resolve().then(() => (init_platform(), platform_exports))).getPlatform().fs.readFileSync(this.signingKeyPath, "utf-8").trim();
      this.signingKey = Buffer.from(keyHex, "hex");
    } catch (err) {
      throw new Error(
        `[IPCClient] Failed to read signing key from ${this.signingKeyPath}: ` + (err instanceof Error ? err.message : String(err))
      );
    }
    const { SocketTransport: SocketTransport2 } = await Promise.resolve().then(() => (init_socket_transport(), socket_transport_exports));
    this.transport = new SocketTransport2({ socketPath: this.socketPath });
    await this.transport.start();
  }
  async disconnect() {
    if (this.transport) {
      await this.transport.stop();
      this.transport = null;
    }
  }
  isConnected() {
    return this.transport?.isReady() ?? false;
  }
  async sendAction(action, payload) {
    if (!this.signingKey) {
      throw new Error("[IPCClient] No signing key available. Call connect() first.");
    }
    if (!this.transport || !this.transport.isReady()) {
      throw new Error("[IPCClient] Not connected. Call connect() first.");
    }
    const id = nanoid();
    const timestamp = (/* @__PURE__ */ new Date()).toISOString();
    const signature = signRequest(this.signingKey, id, timestamp, action, payload);
    const request = {
      id,
      timestamp,
      action,
      payload,
      source: "core",
      signature
    };
    return this.transport.send(request);
  }
};

