        documentId: doc.id,
        docType: doc.type,
        authors: doc.authors?.map((a) => `${a.first_name} ${a.last_name}`) ?? [],
        year: doc.year,
        source: doc.source,
        doi: doc.identifiers?.doi,
        isbn: doc.identifiers?.isbn,
        keywords: doc.keywords ?? [],
        tags: doc.tags ?? [],
